package com.dedhapp3n.pokeldn.ldn

import com.dedhapp3n.pokeldn.za.ZaNetworkParameters
import java.security.MessageDigest
import javax.crypto.Cipher
import javax.crypto.spec.IvParameterSpec
import javax.crypto.spec.SecretKeySpec
import org.junit.Assert.*
import org.junit.Test

/** Exact frames generated by tools/ldn/generate_android_za_protocol1_fixtures.py. */
class LdnProtocolOneTest {
    private val ssid = (0x40..0x4f).map(Int::toByte).toByteArray()
    private val serverRandom = (0x50..0x5f).map(Int::toByte).toByteArray()
    private val bssid = "021122334455".hex()
    private val identity = LdnHostIdentity(bssid, ssid, serverRandom, 0x60616263,
        0x0102030405060708L, 33, 0x1112131415161718L, fixture("advertisement_12345678"))
    private val parameters = LdnHostParameters(1, ZaNetworkParameters.COMM_ID, 1, 6, 2, 6, byteArrayOf(0x20))
    private val host = LdnAdvertisedParticipant(0, "a9fe2101".hex(), bssid, 0, byteArrayOf(0x20), 6)

    @Test fun fullEncryptedAdvertisementMatchesKinnayAndDecryptsToV1() {
        val frame = LdnAdvertisementBuilder.encodeActionFrame(keys(), identity, identity.advertisementNonce,
            listOf(host), parameters)
        assertArrayEquals(fixture("protocol1_action"), frame)
        assertEquals(0x500 + 32 + 24 + 12 + 40, frame.size)
        val header = frame.copyOfRange(36, 76)
        assertEquals(2, header[33].u())
        assertEquals(0x500, header.u16(34))
        assertEquals(0x0100F43008C44000L, header.u64(0))
        assertEquals(1, header.u16(10))
        val key = LdnKeyDerivation(keys(), 1).deriveAdvertiseKey(header.copyOfRange(0, 32))
        val plain = Cipher.getInstance("AES/CTR/NoPadding").run {
            init(Cipher.DECRYPT_MODE, SecretKeySpec(key, "AES"),
                IvParameterSpec(header.copyOfRange(36, 40) + ByteArray(12)))
            doFinal(frame.copyOfRange(76, frame.size))
        }
        val v1 = plain.copyOfRange(32, plain.size)
        assertEquals(0x500, v1.size)
        assertArrayEquals(MessageDigest.getInstance("SHA-256").digest(header + ByteArray(32) + v1),
            plain.copyOfRange(0, 32))
        assertArrayEquals(serverRandom, v1.copyOfRange(0, 16))
        assertEquals(1, v1.u16(16))
        assertEquals((2 shl 10) or 6, v1.u16(20))
        assertEquals(2, v1[22].u())
        assertEquals(1, v1[23].u())
        assertArrayEquals("a9fe2101".hex(), v1.copyOfRange(24, 28))
        assertArrayEquals(bssid, v1.copyOfRange(28, 34))
        assertEquals(1, v1[34].u())
        assertEquals(6, v1.u16(68))
        assertTrue(v1.copyOfRange(80, 472).all { it == 0.toByte() })
        assertEquals(112, v1.u16(474))
        assertArrayEquals(identity.applicationData, v1.copyOfRange(476, 588))
        assertEquals(identity.challengeToken, v1.u64(0x4f8))
    }

    @Test fun plainAuthenticationMatchesKinnayRequestAndResponse() {
        val requestBytes = fixture("protocol1_auth_request")
        assertEquals(0, requestBytes[11].u())
        assertEquals(6 + 0x48 + 0x364, requestBytes.size)
        val request = LdnAuthenticationCodec.decodeRequest(keys(), requestBytes, parameters)
        assertEquals(4, request.version)
        assertEquals("Console", request.username.toString(Charsets.UTF_8))
        assertEquals(6, request.appVersion)
        assertEquals(0, request.platform)
        assertEquals(0x300, request.challenge.size)
        assertEquals(ZaNetworkParameters.COMM_ID, request.localCommunicationId)
        assertEquals(1, request.sceneId)
        assertArrayEquals(ssid, request.ssid)
        assertArrayEquals(serverRandom, request.serverRandom)
        assertThrows(IllegalArgumentException::class.java) {
            LdnAuthenticationCodec.decodeRequest(keys(), requestBytes)
        }
        val authHost = LdnAuthenticationHost(keys(), identity, parameters)
        val outcome = authHost.process("0a0b0c0d0e0f".hex(), requestBytes)
        assertTrue(outcome.requestParsed)
        assertEquals(0, outcome.statusCode)
        assertNotNull(outcome.participant)
        assertArrayEquals(fixture("protocol1_auth_response"), outcome.response)
        assertEquals(0, outcome.response[11].u())
        assertEquals(6 + 0x48 + 0x184, outcome.response.size)
        assertArrayEquals(fixture("protocol1_registered_action"), authHost.currentAdvertisementFrame())
    }

    private fun fixture(name: String) = javaClass.getResourceAsStream("/za/$name.bin")!!.use { it.readBytes() }
    private fun keys() = LdnProdKeysParser.parse("""
        aes_kek_generation_source = 000102030405060708090a0b0c0d0e0f
        aes_key_generation_source = 101112131415161718191a1b1c1d1e1f
        master_key_00 = 202122232425262728292a2b2c2d2e2f
        master_key_12 = 303132333435363738393a3b3c3d3e3f
    """.trimIndent().toByteArray())
    private fun String.hex() = chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    private fun Byte.u() = toInt() and 255
    private fun ByteArray.u16(at: Int) = (this[at].u() shl 8) or this[at + 1].u()
    private fun ByteArray.u64(at: Int): Long = (0 until 8).fold(0L) { value, i -> (value shl 8) or this[at + i].u().toLong() }
}
